/// Detect the board. `octal_psram`: the chip embeds octal PSRAM (GPIO33..37 are
/// taken); `psram`: any PSRAM. Peripherals are only borrowed.
pub fn detect(p: &mut Peripherals, octal_psram: bool, psram: bool) -> Result<BoardId, DetectLog> {
    let mut log = DetectLog { octal_psram, psram, records: [ProbeRecord::default(); 8], count: 0 };
    if cores3_stackchan::CANDIDATE && !(octal_psram && cores3_stackchan::USES_OCTAL_PSRAM_PINS) && (psram || !cores3_stackchan::NEEDS_PSRAM) {
        let mut ok = true;
        // probe `pmic-id` (kumiki,probe-i2c-reg)
        if ok {
            super::probe::i2c_bus_recover(p.GPIO11.reborrow(), p.GPIO12.reborrow());
            let v = super::probe::i2c_read_reg(p.I2C0.reborrow(), p.GPIO12.reborrow(), p.GPIO11.reborrow(), 0x34, 0x03);
            log.push("M5Stack CoreS3 + Stack-chan", "pmic-id", v.map(|b| [b, 0, 0]), 1);
            ok = v == Some(0x4a);
        }
        // probe `ioexp-id` (kumiki,probe-i2c-reg)
        if ok {
            super::probe::i2c_bus_recover(p.GPIO11.reborrow(), p.GPIO12.reborrow());
            let v = super::probe::i2c_read_reg(p.I2C0.reborrow(), p.GPIO12.reborrow(), p.GPIO11.reborrow(), 0x58, 0x10);
            log.push("M5Stack CoreS3 + Stack-chan", "ioexp-id", v.map(|b| [b, 0, 0]), 1);
            ok = v == Some(0x23);
        }
        // probe `base-io-version` (kumiki,probe-i2c-ack)
        if ok {
            super::probe::i2c_bus_recover(p.GPIO11.reborrow(), p.GPIO12.reborrow());
            let v = loop {
                let v = super::probe::i2c_read_reg(p.I2C0.reborrow(), p.GPIO12.reborrow(), p.GPIO11.reborrow(), 0x6f, 0x02);
                if v.is_some_and(|b| b != 0x00 && b != 0xff) || esp_hal::time::Instant::now().duration_since_epoch().as_millis() >= 1200 {
                    break v;
                }
                esp_hal::delay::Delay::new().delay_millis(50);
            };
            log.push("M5Stack CoreS3 + Stack-chan", "base-io-version", v.map(|b| [b, 0, 0]), 1);
            ok = v.is_some_and(|b| b != 0x00 && b != 0xff);
        }
        if ok {
            return Ok(BoardId::M5StackCoreS3Stackchan);
        }
    }
    if cores3::CANDIDATE && !(octal_psram && cores3::USES_OCTAL_PSRAM_PINS) && (psram || !cores3::NEEDS_PSRAM) {
        let mut ok = true;
        // probe `pmic-id` (kumiki,probe-i2c-reg)
        if ok {
            super::probe::i2c_bus_recover(p.GPIO11.reborrow(), p.GPIO12.reborrow());
            let v = super::probe::i2c_read_reg(p.I2C0.reborrow(), p.GPIO12.reborrow(), p.GPIO11.reborrow(), 0x34, 0x03);
            log.push("M5Stack CoreS3", "pmic-id", v.map(|b| [b, 0, 0]), 1);
            ok = v == Some(0x4a);
        }
        // probe `ioexp-id` (kumiki,probe-i2c-reg)
        if ok {
            super::probe::i2c_bus_recover(p.GPIO11.reborrow(), p.GPIO12.reborrow());
            let v = super::probe::i2c_read_reg(p.I2C0.reborrow(), p.GPIO12.reborrow(), p.GPIO11.reborrow(), 0x58, 0x10);
            log.push("M5Stack CoreS3", "ioexp-id", v.map(|b| [b, 0, 0]), 1);
            ok = v == Some(0x23);
        }
        if ok {
            return Ok(BoardId::M5StackCoreS3);
        }
    }
    if atoms3::CANDIDATE && !(octal_psram && atoms3::USES_OCTAL_PSRAM_PINS) && (psram || !atoms3::NEEDS_PSRAM) {
        let mut ok = true;
        // probe `panel-id` (kumiki,probe-dcs-id-3wire)
        if ok {
            let id = super::probe::read_dcs_id_3wire(p.GPIO17.reborrow(), p.GPIO21.reborrow(), p.GPIO15.reborrow(), p.GPIO33.reborrow(), p.GPIO34.reborrow());
            log.push("M5Stack AtomS3", "panel-id", Some(id), 3);
            ok = id == [0, 145, 7];
        }
        if ok {
            return Ok(BoardId::M5StackAtomS3);
        }
    }
    if stopwatch::CANDIDATE && !(octal_psram && stopwatch::USES_OCTAL_PSRAM_PINS) && (psram || !stopwatch::NEEDS_PSRAM) {
        let mut ok = true;
        // probe `pmic-ack` (kumiki,probe-i2c-ack)
        if ok {
            super::probe::i2c_bus_recover(p.GPIO48.reborrow(), p.GPIO47.reborrow());
            let v = super::probe::i2c_read_reg(p.I2C1.reborrow(), p.GPIO47.reborrow(), p.GPIO48.reborrow(), 0x6e, 0x00);
            log.push("M5Stack StopWatch", "pmic-ack", v.map(|b| [b, 0, 0]), 1);
            ok = v.is_some();
        }
        if ok {
            return Ok(BoardId::M5StackStopWatch);
        }
    }
    Err(log)
}

/// Move the chip GPIOs used by M5Stack CoreS3 + Stack-chan out of `Peripherals`.
macro_rules! take_pins_cores3_stackchan {
    ($p:ident) => {
        $crate::esp32s3::generated::cores3_stackchan::Pins {
            i2c0_sda: $p.GPIO12,
            i2c0_scl: $p.GPIO11,
            spi2_sck: $p.GPIO36,
            spi2_mosi: $p.GPIO37,
            spi2_cs: $p.GPIO3,
            lcd_dc: $p.GPIO35,
            i2s1_mclk: $p.GPIO0,
            i2s1_bclk: $p.GPIO34,
            i2s1_ws: $p.GPIO33,
            i2s1_dout: $p.GPIO13,
            i2s1_din: $p.GPIO14,
            uart1_tx: $p.GPIO6,
            uart1_rx: $p.GPIO7,
        }
    };
}

